interface Greeter {
    String greet(String name);

    // Default method — optional to override
    default void greetAll(List<String> names) {
        names.forEach(name -> System.out.println(greet(name)));
    }
}

class FormalGreeter implements Greeter {
    public String greet(String name) { return "Good day, " + name; }
    // greetAll() inherited from interface — no override needed
}
