interface Validator<T> {
    boolean validate(T value);

    // Static factory method
    static <T> Validator<T> combine(Validator<T> v1, Validator<T> v2) {
        return value -> v1.validate(value) && v2.validate(value);
    }
}

// Usage:
Validator<String> notEmpty = s -> !s.isEmpty();
Validator<String> notTooLong = s -> s.length() <= 100;
Validator<String> combined = Validator.combine(notEmpty, notTooLong);

// From JDK: Comparator.comparing() is a static interface method
List.sort(Comparator.comparing(User::getName));
